def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    yesterday_bids = []
    dangerous_prev = 0.0
    rich_count = 0
    desperate_count = 0
    for agent_id, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace') or {}
        prev_bid = prev.get('bid')
        if prev_bid is not None:
            yesterday_bids.append(prev_bid)
            if prev_bid > dangerous_prev:
                dangerous_prev = prev_bid

    slots = supply / WATER_REQ
    scarcity = slots < (len(alive) + 1)
    very_tight = slots <= max(1.2, len(alive) * 0.45)

    if yesterday_bids:
        ref_bid = dangerous_prev
    else:
        ref_bid = DAILY_SALARY * 0.55

    if hp <= 2 or no_water >= 2:
        bid = max(DAILY_SALARY * 0.95, ref_bid + 6.0)
    elif hp <= 4 or no_water >= 1:
        if scarcity:
            bid = max(DAILY_SALARY * 0.78, ref_bid + 3.0)
        else:
            bid = max(DAILY_SALARY * 0.58, ref_bid * 0.72)
    else:
        if very_tight:
            bid = max(DAILY_SALARY * 0.72, ref_bid + 2.0)
        elif scarcity:
            bid = max(DAILY_SALARY * 0.52, ref_bid * 0.82)
        else:
            bid = DAILY_SALARY * 0.34

    if rich_count >= 2 and hp >= 5 and no_water == 0 and scarcity:
        bid = min(bid, DAILY_SALARY * 0.48)

    if desperate_count >= 2 and scarcity:
        bid += 4.0

    if day >= 8 and hp <= 5:
        bid = max(bid, DAILY_SALARY * 0.82)

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, max(0.0, budget * 0.72))

    bid = max(0.0, min(budget, bid))
    return bid

