    budget = my_status['budget']
    hp = my_status['hp']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if not yesterday_bids:
        return min(budget, DAILY_SALARY * 0.5)
    max_yesterday = max(yesterday_bids)
    avg_yesterday = sum(yesterday_bids) / len(yesterday_bids)
    if hp <= 2:
        bid = max(DAILY_SALARY * 0.9, max_yesterday + 1.0)
    elif hp <= 4:
        bid = max(DAILY_SALARY * 0.6, avg_yesterday)
    else:
        bid = min(DAILY_SALARY * 0.4, avg_yesterday * 0.9)
    return min(budget, bid)
